mapper.select:

where s.del_flag = '0'

  and s.teacher_user_id = #{teacherUserId}

  and s.start_time < #{endTime}
  and s.end_time > #{beginTime}
order by s.start_time, s.id


where s.del_flag = '0'
  and exists (
      select 1 from cf_schedule_student st
      where st.session_id = s.id and st.student_id = #{studentId}
  )
  and s.start_time < #{endTime}
  and s.end_time > #{beginTime}
order by s.start_time, s.id

select count(1) from cf_schedule_session s
where s.del_flag = '0'
  and s.teacher_user_id = #{teacherUserId}
  and s.start_time < #{endTime}
  and s.end_time > #{startTime}
  and s.id <> #{excludeId}

select count(1) from cf_schedule_session s
inner join cf_schedule_student st on st.session_id = s.id
where s.del_flag = '0'
  and st.student_id = #{studentId}
  and s.start_time < #{endTime}
  and s.end_time > #{startTime}
  and s.id <> #{excludeId}


where s.del_flag = '0'
  and s.fee_schedule_id = #{feeScheduleId}
  and s.start_time = #{startTime}
limit 1


where s.del_flag = '0'
  and s.fee_id = #{feeId}
  and s.start_time = #{startTime}
limit 1

mapper.update:
update cf_schedule_session
set del_flag = '2', update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id} and del_flag = '0'

update cf_schedule_session
set del_flag = '2', update_by = #{updateBy}, update_time = #{updateTime}
where fee_id = #{feeId} and source = 'fee' and edited_flag = '0' and del_flag = '0'
